import heapq

def top_k_frequent_chars(sequence, k):
    frequency_table = generate_frequency_table(sequence)
    heap = []
    for char, count in frequency_table.items():
        if len(heap) < k:
            heapq.heappush(heap, (count, -ord(char), char))
