dll.insert_at_beginning(3)
dll.insert_at_beginning(2)
dll.insert_at_beginning(1)
dll.insert_at_end(4)
dll.insert_at_end(5)
dll.delete_node(3)
print("Length:", dll.length())
dll.traverse_forward()  # Output: 1 2 4 5
dll.traverse_backward() # Output: 5 4 2 1
```

