    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def gcf_three_primes(a, b, c):
    gcf = min(a, b, c)
    while gcf > 1:
        if is_factor(gcf, a) and is_factor(gcf, b) and is_factor(gcf, c):
