def replace_characters(string):
    html_entities = {
        ord('"'): '&quot;',
        ord('&'): '&amp;',
        ord('<'): '&lt;',
        ord('>'): '&gt;'
    }

    output = ''
    for char in string:
        if ord(char) < 128:
            output += html_entities.get(ord(char), char)
